package vn.iotstar.service; import lombok.RequiredArgsConstructor; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import vn.iotstar.dto.*; import vn.iotstar.entity.*; import vn.iotstar.repository.*;
@Service @RequiredArgsConstructor public class AuthService{final UserRepository users;final RoleRepository roles;final PasswordEncoder encoder;final OtpService otp; public void register(RegisterDTO d){if(!d.getPassword().equals(d.getConfirmPassword()))throw new IllegalArgumentException("Mật khẩu không khớp");if(users.existsByUsernameOrEmail(d.getUsername(),d.getEmail()))throw new IllegalArgumentException("Username hoặc email đã tồn tại");var u=new User();u.setUsername(d.getUsername());u.setEmail(d.getEmail().toLowerCase());u.setFullName(d.getFullName());u.setPassword(encoder.encode(d.getPassword()));u.setRole(roles.findByName("USER").orElseThrow());u.setEnabled(false);users.save(u);otp.issue(u.getEmail(),OtpPurpose.REGISTER);} public void verify(String e,String c){otp.verify(e,c,OtpPurpose.REGISTER);var u=users.findByEmail(e).orElseThrow();u.setEnabled(true);users.save(u);} public void resend(String e){otp.issue(e,OtpPurpose.REGISTER);} public void resetRequest(String e){if(users.findByEmail(e).isPresent())otp.issue(e,OtpPurpose.RESET_PASSWORD);} public void reset(String e,String c,ResetPasswordDTO d){if(!d.getPassword().equals(d.getConfirmPassword()))throw new IllegalArgumentException("Mật khẩu không khớp");otp.verify(e,c,OtpPurpose.RESET_PASSWORD);var u=users.findByEmail(e).orElseThrow();u.setPassword(encoder.encode(d.getPassword()));users.save(u);}}
